import os
import time
import requests


ASSEMBLYAI_API_KEY = os.environ["ASSEMBLYAI_API_KEY"]
ASSEMBLYAI_BASE_URL = "https://api.assemblyai.com/v2"

HEADERS = {
    "authorization": ASSEMBLYAI_API_KEY,
    "content-type": "application/json",
}


def _upload_file(audio_file_path: str) -> str:
    upload_url = f"{ASSEMBLYAI_BASE_URL}/upload"

    def read_file():
        with open(audio_file_path, "rb") as f:
            while True:
                chunk = f.read(5 * 1024 * 1024)
                if not chunk:
                    break
                yield chunk

    response = requests.post(
        upload_url,
        headers={"authorization": ASSEMBLYAI_API_KEY},
        data=read_file(),
        timeout=300,
    )
    response.raise_for_status()
    return response.json()["upload_url"]


def submit_batch_transcription(audio_file_path: str, language_code: str = "en") -> str:
    audio_url = _upload_file(audio_file_path)
    response = requests.post(
        f"{ASSEMBLYAI_BASE_URL}/transcript",
        headers=HEADERS,
        json={
            "audio_url": audio_url,
            "language_code": language_code,
            "speech_model": "best",
        },
        timeout=60,
    )
    response.raise_for_status()
    return response.json()["id"]


def get_transcription_result(transcript_id: str) -> dict:
    response = requests.get(
        f"{ASSEMBLYAI_BASE_URL}/transcript/{transcript_id}",
        headers=HEADERS,
        timeout=60,
    )
    response.raise_for_status()
    return response.json()


def transcribe_file_batch(audio_file_path: str, language_code: str = "en", poll_interval_seconds: int = 5) -> dict:
    transcript_id = submit_batch_transcription(audio_file_path, language_code=language_code)

    while True:
        result = get_transcription_result(transcript_id)
        status = result.get("status")

        if status == "completed":
            return {
                "id": transcript_id,
                "status": status,
                "text": result.get("text", ""),
                "raw": result,
            }

        if status == "error":
            raise RuntimeError(f"AssemblyAI transcription failed: {result.get('error', 'unknown error')}")

        time.sleep(poll_interval_seconds)
